/// Return the area covered by the union of axis-aligned rectangles.
/// Each rectangle is (x1, y1, x2, y2), where (x1, y1) and (x2, y2) are two
/// opposite corners given in any order. Area covered by several rectangles
/// counts once. A rectangle with zero width or zero height covers nothing, and
/// an empty list gives 0.
///
/// Return -1 if any coordinate has absolute value greater than 1_000_000.
/// >>> rect_union_area(vec![(0, 0, 4, 4), (2, 2, 6, 6)])
/// 28
/// >>> rect_union_area(vec![(3, 3, 1, 1)])
/// 4
fn rect_union_area(rects: Vec<(i64, i64, i64, i64)>) -> i64 {
    let limit = 1_000_000;
    let mut norm: Vec<(i64, i64, i64, i64)> = Vec::new();
    for &(x1, y1, x2, y2) in &rects {
        if x1.abs() > limit || y1.abs() > limit || x2.abs() > limit || y2.abs() > limit {
            return -1;
        }
        // Corners may come in any order; store (left, bottom, right, top).
        norm.push((x1.min(x2), y1.min(y2), x1.max(x2), y1.max(y2)));
    }
    let mut xs: Vec<i64> = norm.iter().flat_map(|r| [r.0, r.2]).collect();
    let mut ys: Vec<i64> = norm.iter().flat_map(|r| [r.1, r.3]).collect();
    xs.sort();
    xs.dedup();
    ys.sort();
    ys.dedup();
    let mut total = 0;
    // Coordinate compression: each grid cell is either fully covered or not.
    for i in 0..xs.len().saturating_sub(1) {
        for j in 0..ys.len().saturating_sub(1) {
            if covered(&norm, xs[i], ys[j], xs[i + 1], ys[j + 1]) {
                total += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
            }
        }
    }
    total
}

// True if one rectangle contains the cell [x0, x1] x [y0, y1].
fn covered(rects: &[(i64, i64, i64, i64)], x0: i64, y0: i64, x1: i64, y1: i64) -> bool {
    rects.iter().any(|&(a, b, c, d)| a <= x0 && x1 <= c && b <= y0 && y1 <= d)
}
